-- fitness: 같은 나이 · 성별 참가자의 인증 등급별 비율(AI assess peer_distribution 과 같은 표).
-- scripts/grade_distribution_to_sql.py --create-table 가 생성한다. 손으로 고치지 말고, AI 릴리스가 바뀌면 새 V 파일로 다시 만든다.
-- 출처: family-fitness-ai HEAD 79e5b4793dc4c93175aa98ff8d7143e9fc5e834f (입력 파일 마지막 변경 1d524f2, 2026-09-17T21:14:50+09:00)
--   data/release/grade_distribution.csv 1048행 · 연령대 유아기 · 유소년 · 청소년 · 성인 · 어르신. 원자료는 국민체력100 인증 결과(CRTFC_FLAG_NM).
-- 나이는 유아기만 개월, 나머지는 만 나이다. 성인 · 청소년은 2025년 6월부터 1~6등급 체계라 네 비율의 합이
--   1 에 못 미칠 수 있다 — 그대로 싣는다.
-- 표를 통째로 바꾼다. PostgreSQL 과 H2(MODE=PostgreSQL) 양쪽에서 그대로 실행되는 문법만 쓴다.
create table fitness_grade_distribution (
    id        bigint generated by default as identity,
    age_group varchar(10)  not null,
    sex       varchar(1)   not null,
    age       smallint     not null,
    grade     varchar(10)  not null,
    n         integer      not null,
    ratio     numeric(5, 4) not null,
    constraint pk_fitness_grade_distribution primary key (id),
    constraint uq_fitness_grade_distribution unique (age_group, sex, age, grade),
    constraint ck_fitness_grade_distribution_sex check (sex in ('M', 'F')),
    constraint ck_fitness_grade_distribution_grade check (grade in ('1등급', '2등급', '3등급', '참가')),
    constraint ck_fitness_grade_distribution_ratio check (ratio between 0 and 1)
);
delete from fitness_grade_distribution;
